WITH parsed AS (SELECT id, customer_id, items, ARRAY_JOIN(ARRAY_SORT(coupon_codes), ',') AS coupons_text, EXISTS(items, i -> i.price > 100) AS has_premium_item, TRANSFORM(items, i -> i.product_id) AS product_ids, ARRAY_CONTAINS(MAP_KEYS(attributes), 'weight_kg') AS has_weight_kg FROM carts) SELECT customer_id, COUNT(DISTINCT id) AS distinct_ids, COUNT(*) AS row_count, COUNT(*) AS event_count, COUNT(*) AS event_count_2, COUNT(*) AS cnt, COUNT(*) AS event_count_3 FROM parsed GROUP BY customer_id HAVING event_count_3 < 1000
